  const state={lang:saved.lang==='csharp'?'csharp':'ruby',done:Array.isArray(saved.done)?saved.done:[],solved:Array.isArray(saved.solved)?saved.solved:[],bookmarks:Array.isArray(saved.bookmarks)?saved.bookmarks:[],drafts:saved.drafts&&typeof saved.drafts==='object'?saved.drafts:{},inputs:saved.inputs&&typeof saved.inputs==='object'?saved.inputs:{},lastLesson:typeof saved.lastLesson==='string'?saved.lastLesson:'io'};
  let filter='すべて',query='',lessonTab='read',currentVisualizer=null,visualType='binary',currentEditor=null,runController=null,runBusy=false,toastTimer;
