  function side(){const n=LESSONS.filter(l=>state.done.includes(l.id)).length;$('#side-progress').innerHTML=`<div class="progress-label"><span>学習の進み具合</span><b>${n} / ${LESSONS.length}</b></div><div class="progress-bar" role="progressbar" aria-label="レッスンの完了数" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${LESSONS.length}"><span style="width:${n/LESSONS.length*100}%"></span></div>`;$$('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===state.lang);b.setAttribute('aria-pressed',String(b.dataset.lang===state.lang));});}
  function pageHeading(eyebrow,title,description,extra=''){return `<div class="page-title-row"><div><div class="section-eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
